  const { pkg, pkgPath } = packageDeps(cwd);
  if (pkg) {
    let changed = false;
    const details = [];
    const scripts = { ...pkg.scripts || {} };
    if (!scripts["show-report"]) {
      scripts["show-report"] = "merv show-report";
      changed = true;
      details.push("added show-report");
    }
    if (!scripts["show-logs"]) {
      scripts["show-logs"] = "merv show-logs";
      changed = true;
      details.push("added show-logs");
    }
    if (sampleScript) {
      const want = language === "typescript" ? "npx tsx scripts/custom-report.ts" : "node scripts/custom-report.mjs";
      if (!scripts["merv:report"]) {
        scripts["merv:report"] = want;
        changed = true;
        details.push("added merv:report");
      }
    }
    if (changed) {
      pkg.scripts = scripts;
      writeJsonFile(pkgPath, pkg);
      steps.push({
        step: "package.json scripts",
        action: "updated",
        path: pkgPath,
        detail: `${details.join(", ")} (left other package.json fields unchanged)`
      });
    } else {
      steps.push({
        step: "package.json",
        action: "skipped",
        path: pkgPath,
        detail: "MERV scripts already present"
      });
    }
  } else {
    steps.push({
      step: "package.json",
      action: "failed",
      detail: "No package.json in this folder \u2014 run npm init first"
    });
  }
  if (language === "typescript") {
    const tsPath = path3.join(cwd, "tsconfig.json");
    if (fs3.existsSync(tsPath) && !force) {
      steps.push({
        step: "tsconfig.json",
        action: "skipped",
        path: tsPath,
        detail: "already exists"
      });
    } else {
      const action = writeFileSmart(tsPath, JSON.stringify(TSCONFIG, null, 2), force);
      steps.push({ step: "tsconfig.json", action, path: tsPath });
    }
  } else {
    const jsPath = path3.join(cwd, "jsconfig.json");
    if (fs3.existsSync(jsPath) && !force) {
      steps.push({
        step: "jsconfig.json",
        action: "skipped",
        path: jsPath,
        detail: "already exists"
      });
    } else if (!fs3.existsSync(path3.join(cwd, "tsconfig.json"))) {
      const action = writeFileSmart(jsPath, JSON.stringify(JSCONFIG, null, 2), force);
      steps.push({ step: "jsconfig.json", action, path: jsPath });
    }
  }
